"""Write the portfolio's results file (data/voiceResults.ts) from evals/results/summary.json.

  python scripts/site_results.py ../ai-portfolio/data/voiceResults.ts
"""
import json
import sys
from pathlib import Path

summary = json.loads(Path("evals/results/summary.json").read_text())
body = json.dumps(summary, indent=2)
out = (
    "// Generated by scripts/site_results.py in the voice-to-tasks repository. Do not edit by hand.\n"
    "export type VoiceConfig = {\n  utterances: number; words: number; errors: number; wer: number; ci_lo: number; ci_hi: number;\n"
    "  perfect: number; audio_seconds: number; median_latency: number; p90_latency: number; speed_x_realtime: number;\n"
    "  worst: { id: string; errors: number; words: number; reference: string; hypothesis: string }[];\n};\n"
    f"export const VOICE_BENCH: Record<string, VoiceConfig> = {body};\n"
)
Path(sys.argv[1]).write_text(out)
print("wrote", sys.argv[1], list(summary))
